const request = $json;
const headers = request.headers ?? {};
const suppliedSecret = headers['x-granize-secret'] ?? headers['X-Granize-Secret'];
if (!suppliedSecret || suppliedSecret !== $env.N8N_SHARED_SECRET) throw new Error('Webhook não autorizado');

const body = request.body ?? request;
const evolution = body.payload ?? {};
const data = evolution.data ?? {};
if (data.key?.fromMe) return [];

const remoteJid = String(data.key?.remoteJid ?? '');
if (!remoteJid || remoteJid.endsWith('@g.us')) return [];
const message = data.message ?? {};
const text = String(message.conversation ?? message.extendedTextMessage?.text ?? message.imageMessage?.caption ?? message.videoMessage?.caption ?? '').trim();
const hasAudio = Boolean(message.audioMessage);
if (!text && !hasAudio) return [];

return [{ json: { instanceName: body.instanceName, phone: remoteJid.replace(/@.+$/, ''), externalId: String(data.key?.id ?? `${body.instanceName}-${Date.now()}`), text, inputType: hasAudio && !text ? 'audio' : 'text', mediaMessage: hasAudio ? data : null } }];

const original = $('Preparar mensagem').item.json;
const text = String($json.text ?? '').trim();
if (!text) throw new Error('O áudio não produziu uma transcrição.');
return [{ json: { ...original, text, inputType: 'audio' } }];

const text = String($json.text ?? '').trim();
if (!text) return [];
const normalized = text.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const base = { instanceName: $json.instanceName, phone: $json.phone, externalId: $json.externalId, inputType: $json.inputType, understoodText: text };
const audioIntro = $json.inputType === 'audio' ? `🎙️ Entendi: _${text}_\n\n` : '';
const summaryWords = ['saldo', 'resumo', 'extrato', 'como estao minhas financas', 'quanto tenho'];
if (summaryWords.some((word) => normalized.includes(word))) return [{ json: { ...base, action: 'summary' } }];

const incomeWords = ['recebi', 'ganhei', 'entrou', 'entrada', 'salario', 'renda', 'pix recebido'];
const expenseWords = ['gastei', 'paguei', 'comprei', 'despesa', 'saiu', 'debito'];
const isIncome = incomeWords.some((word) => normalized.includes(word));
const isExpense = expenseWords.some((word) => normalized.includes(word));
const currencyMatch = text.match(/(?:r\$\s*)?(\d{1,3}(?:\.\d{3})*,\d{1,2}|\d+(?:[.,]\d{1,2})?)/i);

if ((isIncome || isExpense) && currencyMatch) {
  const amount = Number(currencyMatch[1].replace(/\./g, '').replace(',', '.'));
  if (Number.isFinite(amount) && amount > 0) {
    const type = isIncome && !isExpense ? 'income' : 'expense';
    const removableWords = [...incomeWords, ...expenseWords].sort((a, b) => b.length - a.length);
    let description = text;
    for (const word of removableWords) description = description.replace(new RegExp(word, 'ig'), ' ');
    description = description.replace(currencyMatch[0], ' ').replace(/\b(no|na|em|de|do|da|um|uma|reais?)\b/gi, ' ').replace(/\s+/g, ' ').trim();
    if (!description) description = type === 'income' ? 'Receita pelo WhatsApp' : 'Despesa pelo WhatsApp';
    description = description.charAt(0).toLocaleUpperCase('pt-BR') + description.slice(1);
    const confirmation = `${audioIntro}${type === 'income' ? '✅ Receita' : '✅ Despesa'} registrada!\n${description}: R$ ${amount.toFixed(2).replace('.', ',')}\n\nDigite *saldo* para ver seu resumo.`;
    return [{ json: { ...base, action: 'transaction', type, description: description.slice(0, 120), amount, transactionDate: new Date().toISOString().slice(0, 10), confirmation } }];
  }
}

return [{ json: { ...base, action: 'help', responseText: `${audioIntro}Não consegui identificar um lançamento.\n\nVocê pode dizer ou escrever:
• *Gastei 58 no restaurante*\n• *Recebi 2500 de salário*\n• *Saldo* ou *Resumo*` } }];

if ($json.action !== 'help') return [{ json: $json }];
const text = String($json.understoodText ?? '').trim();
const normalized = text.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const incomePattern = /\b(ganh(?:ei|ou|amos|ar|ado)|receb(?:i|eu|emos|er|ido)|entrou|caiu|depositaram|vendi|lucrei|faturei|salario|renda|pix recebido|credito|reembolso|comissao|bonus|premio)\b/i;
const expensePattern = /\b(gast(?:ei|ou|amos|ar|ado)|pag(?:uei|ou|amos|ar|ado)|compr(?:ei|ou|amos|ar|ado)|saiu|debitaram|descontaram|despesa|boleto|pix enviado|transferi|custou)\b/i;
const amountMatch = text.match(/r\$\s*(\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?|\d+(?:[.,]\d{1,2})?)/i) || text.match(/(\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?|\d+(?:[.,]\d{1,2})?)\s*(?:reais?|conto[s]?)\b/i) || text.match(/\b(\d+(?:[.,]\d{1,2})?)\b/);
const isIncome = incomePattern.test(normalized);
const isExpense = expensePattern.test(normalized);
if ((!isIncome && !isExpense) || !amountMatch) return [{ json: $json }];
const amount = Number(String(amountMatch[1]).replace(/\./g, '').replace(',', '.'));
if (!Number.isFinite(amount) || amount <= 0) return [{ json: $json }];
const type = isIncome && !isExpense ? 'income' : 'expense';
const categoryRules = type === 'income' ? [
  ['Salário', /salario|ordenado|pagamento da empresa/], ['Freelance', /freela|freelance|cliente|servico/], ['Vendas', /vendi|venda|faturei/], ['Investimentos', /dividendo|rendimento|investimento|juros/], ['Reembolso', /reembolso|estorno/], ['Presente', /presente|premio|bonus/]
] : [
  ['Alimentação', /restaurante|lanche|almoco|jantar|comida|ifood|padaria/], ['Mercado', /mercado|supermercado|hortifruti/], ['Transporte', /uber|99|taxi|onibus|combustivel|gasolina|estacionamento/], ['Moradia', /aluguel|condominio|casa/], ['Contas', /luz|energia|agua|internet|telefone|boleto/], ['Saúde', /farmacia|remedio|medico|consulta|dentista/], ['Educação', /curso|faculdade|escola|livro/], ['Lazer', /cinema|show|viagem|jogo/], ['Assinaturas', /netflix|spotify|assinatura|mensalidade/], ['Compras', /roupa|sapato|shopping|comprei/]
];
const matched = categoryRules.find(([, pattern]) => pattern.test(normalized));
const category = matched ? matched[0] : type === 'income' ? 'Outros ganhos' : 'Outras despesas';
let description = text.replace(amountMatch[0], ' ').replace(incomePattern, ' ').replace(expensePattern, ' ').replace(/\b(eu|acabei|de|agora|hoje|ontem|anteontem|um|uma|reais?|conto[s]?|no|na|em|do|da|para|por)\b/gi, ' ').replace(/\s+/g, ' ').trim();
if (description.length < 3) description = category; else description = description.charAt(0).toLocaleUpperCase('pt-BR') + description.slice(1);
const date = new Date();
if (/\bontem\b/.test(normalized)) date.setDate(date.getDate() - 1);
if (/\banteontem\b/.test(normalized)) date.setDate(date.getDate() - 2);
const audioIntro = $json.inputType === 'audio' ? `🎙️ Entendi: _${text}_\n\n` : '';
const label = type === 'income' ? 'Ganho' : 'Despesa';
const confirmation = `${audioIntro}✅ ${label} registrado!\n${description}: R$ ${amount.toFixed(2).replace('.', ',')}\nCategoria: ${category}\n\nDigite *saldo* para ver seu resumo.`;
return [{ json: { ...$json, action: 'transaction', type, category, description: description.slice(0, 120), amount, transactionDate: date.toISOString().slice(0, 10), confirmation } }];

const data = { ...$json };
if (data.action !== 'transaction') return [{ json: data }];
const text = String(data.understoodText ?? '').trim();
const normalized = text.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const transactionTime = new Intl.DateTimeFormat('pt-BR', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'America/Sao_Paulo' }).format(new Date());
const largeMatch = normalized.match(/\b(\d+(?:[.,]\d+)?)\s*(mil|k)\b/i);
if (!largeMatch) return [{ json: { ...data, transactionTime } }];
const baseValue = Number(largeMatch[1].replace(',', '.'));
if (!Number.isFinite(baseValue) || baseValue <= 0) return [{ json: { ...data, transactionTime } }];
const amount = baseValue * 1000;
const category = String(data.category || (data.type === 'income' ? 'Outros ganhos' : 'Outras despesas'));
const incomePattern = /\b(ganh(?:ei|ou|amos|ar|ado)|receb(?:i|eu|emos|er|ido)|entrou|caiu|depositaram|vendi|lucrei|faturei|salario|renda|pix recebido|credito|reembolso|comissao|bonus|premio)\b/i;
const expensePattern = /\b(gast(?:ei|ou|amos|ar|ado)|pag(?:uei|ou|amos|ar|ado)|compr(?:ei|ou|amos|ar|ado)|saiu|debitaram|descontaram|despesa|boleto|pix enviado|transferi|custou)\b/i;
let description = text.replace(largeMatch[0], ' ').replace(incomePattern, ' ').replace(expensePattern, ' ').replace(/\b(eu|acabei|de|agora|hoje|ontem|anteontem|um|uma|reais?|conto[s]?|no|na|em|do|da|para|por)\b/gi, ' ').replace(/\s+/g, ' ').trim();
if (description.length < 3 || /^mil$/i.test(description)) description = category; else description = description.charAt(0).toLocaleUpperCase('pt-BR') + description.slice(1);
const audioIntro = data.inputType === 'audio' ? `🎙️ Entendi: _${text}_\n\n` : '';
const label = data.type === 'income' ? 'Ganho' : 'Despesa';
const confirmation = `${audioIntro}✅ ${label} registrado!\n${description}: R$ ${amount.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}\nCategoria: ${category}\nHorário: ${transactionTime}`;
return [{ json: { ...data, amount, description: description.slice(0, 120), transactionTime, confirmation } }];
